    #Node Map Range
    def interpolate(
        self,
        to_min: Vector = None,
        to_max: Vector = None,
        clamp: bool = True,
        interpolation_type: T_INTERPOLATION_TYPE_1 = 'LINEAR'):
        """Node Map Range.
        
        Jump: False
        
        **Fixed inputs**
        - Node parameter 'data_type' = 'FLOAT_VECTOR'
        - Socket 'From Min' = 0.0
        - Socket 'From Max' = 1.0
        - Socket 'Steps' = None
        
        Parameters
        ----------
        interpolation_type : {'LINEAR', 'STEPPED', 'SMOOTHSTEP', 'SMOOTHERSTEP'}, optional
            Node parameter 'interpolation_type' (default: 'LINEAR')
        clamp : VALUE, optional
            Node parameter 'clamp' (default: True)
        to_min : Vector, optional
            Socket 'To Min' (default: None)
        to_max : Vector, optional
            Socket 'To Max' (default: None)
        

        Returns
        -------
        Socket
            Default output socket.
        """
        node = Node(
            'Map Range',
            named_sockets={'ID_Vector': self, 'ID_From_Min_FLOAT3': 0.0, 'ID_From_Max_FLOAT3': 1.0, 'ID_To_Min_FLOAT3': to_min, 'ID_To_Max_FLOAT3': to_max, 'ID_Steps_FLOAT3': None},
            interpolation_type=interpolation_type,
            data_type='FLOAT_VECTOR',
            clamp=clamp)
        
        return node._out

    #Node Switch
    def switch_false( self, switch: Boolean = None, false: Vector = None):
        """Node Switch.
        
        Jump: True
        
        **Fixed inputs**
        - Node parameter 'input_type' = 'VECTOR'
        
        Parameters
        ----------
        switch : Boolean, optional
            Socket 'Switch' (default: None)
        false : Vector, optional
            Socket 'False' (default: None)
        

        Returns
        -------
        Self
            The updated receiver, or its owning geometry for a domain.
            Updates self from the default output socket.
        """
        node = Node(
            'Switch',
            named_sockets={'ID_Switch': switch, 'ID_False': false, 'ID_True': self},
            input_type='VECTOR')
        
        self._jump(node._out)
        return self.self_return

    #Node Switch
    @classmethod
    def Switch( cls, switch: Boolean = None, false: Vector = None, true: Vector = None):
        """Node Switch.
        
        Jump: False
        
        **Fixed inputs**
        - Node parameter 'input_type' = 'VECTOR'
        
        Parameters
        ----------
        switch : Boolean, optional
            Socket 'Switch' (default: None)
        false : Vector, optional
            Socket 'False' (default: None)
        true : Vector, optional
            Socket 'True' (default: None)
        

        Returns
        -------
        Self
            Default output socket wrapped in the calling class.
        """
        node = Node(
            'Switch',
            named_sockets={'ID_Switch': switch, 'ID_False': false, 'ID_True': true},
            input_type='VECTOR')
        
        return cls(node._out)
